def solve_test_input():
    # Test input
    grid = [
        [8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 5, 8, 8],
        [8, 5, 5, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8],
        [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8]
    ]

    rows = len(grid)
    cols = len(grid[0])

    # Find solitary 5s (no other 5s in 8 neighboring cells)
    def count_neighbors(grid, r, c, val):
        count = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == val:
                        count += 1
        return count

    solitary_5s = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5 and count_neighbors(grid, r, c, 5) == 0:
                solitary_5s.append((r, c))

    print(f"Solitary 5s found: {solitary_5s}")

    # Create output grid - copy input, then change neighbors of solitary 5s to 3
    output = [row[:] for row in grid]

    for sr, sc in solitary_5s:
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = sr + dr, sc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if output[nr][nc] != 5:  # Only change background, not other 5s
                        output[nr][nc] = 3

    return output

