rows, cols = 3, 27
marker_val = 5

def get_nearest_marker(r, c, grid, val):
    min_dist = float('inf')
    nearest = None
    for mr in range(rows):
        for mc in range(cols):
            if grid[mr][mc] == val:
                d = abs(r - mr) + abs(c - mc)
                if d < min_dist:
                    min_dist = d
                    nearest = (mr, mc)
    return nearest, min_dist

# For each cell, find nearest marker
output_nearest = [[None]*cols for _ in range(rows)]
for r in range(rows):
    for c in range(cols):
        nearest, dist = get_nearest_marker(r, c, test_input, marker_val)
        if nearest is not None:
            output_nearest[r][c] = test_input[r][c]
        else:
